const mensaje = $('Webhook').item.json.body.mensaje;
const systemPrompt = `Eres un clasificador para Reviive, un taller de restauracion de objetos con valor emocional. Analiza el mensaje del usuario y responde SOLO con un JSON exacto: {"riesgo": "bajo|medio|alto", "motivo_riesgo": "string breve o vacio", "intencion": "pedidos|proveedores|acompanamiento"}. Usa riesgo=alto SOLO si el mensaje muestra senales claras de crisis emocional severa, ideas de autolesion, o angustia extrema que requiera atencion humana inmediata -- no por tristeza o nostalgia normal de un duelo. Usa intencion=pedidos si el usuario pregunta por el estado de un pedido u orden existente. Usa intencion=proveedores si el usuario busca un taller o proveedor especifico para su objeto. En cualquier otro caso usa intencion=acompanamiento.`;

return [{
  json: {
    openaiPayload: {
      model: 'gpt-4o-mini',
      response_format: { type: 'json_object' },
      temperature: 0,
      max_tokens: 200,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: mensaje },
      ],
    },
  },
}];

const resp = $json;
let riesgo = 'bajo';
let motivo = '';
let intencion = 'acompanamiento';

try {
  if (!resp.error && resp.choices && resp.choices.length) {
    const parsed = JSON.parse(resp.choices[0].message.content);
    if (['bajo', 'medio', 'alto'].includes(parsed.riesgo)) riesgo = parsed.riesgo;
    if (typeof parsed.motivo_riesgo === 'string') motivo = parsed.motivo_riesgo;
    if (['pedidos', 'proveedores', 'acompanamiento'].includes(parsed.intencion)) intencion = parsed.intencion;
  }
} catch (e) {
  // ante cualquier duda, se sigue con el comportamiento por defecto (acompanamiento, riesgo bajo)
}

return [{ json: { riesgo, motivo, intencion } }];

const riesgo = $('Procesar clasificacion').item.json.riesgo;
const intencion = $('Procesar clasificacion').item.json.intencion;
const agente = riesgo === 'alto' ? 'seguridad' : intencion;

const body = {
  conversacion_id: $('Webhook').item.json.body.conversacion_id,
  agente,
  agent_version: 'v1',
};

return [{ json: { bodyString: JSON.stringify(body) } }];

const mensajeSeguridad = 'Gracias por confiar en Reviive para contarme esto. Quiero asegurarme de que estes bien: si sientes que esto es una emergencia o una crisis, por favor contacta a la Linea de la Vida (Colombia) al 192 opcion 4, o acude a un profesional de salud mental de confianza. Estoy aqui para acompanarte con tu recuerdo cuando te sientas lista o listo; tambien avisamos a nuestro equipo humano para que pueda apoyarte.';

return [{
  json: {
    run_id: $('Registrar inicio de agente').item.json.run_id,
    reply: mensajeSeguridad,
    status: 'completado',
    input_tokens: null,
    output_tokens: null,
    evaluation_flags: ['riesgo_emocional'],
  },
}];

const mensaje = $('Webhook').item.json.body.mensaje;
const intencion = $('Procesar clasificacion').item.json.intencion;

const pedidosRaw = ($('Obtener pedidos usuario').item.json.results) || [];
const pedidosResumen = pedidosRaw.slice(0, 3).map((p) => ({
  codigo: p.codigo,
  estado: p.estado,
  objeto: p.resumen && p.resumen.objeto,
}));

const proveedoresRaw = ($('Obtener proveedores validados').item.json.results) || [];
const proveedoresResumen = proveedoresRaw.slice(0, 5).map((p) => ({
  nombre_taller: p.nombre_taller,
  ciudad: p.ciudad,
  calificacion: p.calificacion,
}));

const systemPrompt = `Eres Alma, la asistente de inteligencia artificial de Reviive, un taller que restaura objetos con valor emocional. Tu tono es calido, cercano, elegante y profesional, nunca frio ni robotico, y nunca te presentas como psicologa ni sustituyes atencion profesional. Respondes siempre en espanol, en 2 a 4 frases. Nunca confirmes precios ni tiempos de entrega exactos ni inventes estados de pedidos o proveedores: solo puedes mencionar los pedidos reales listados en pedidos_recientes y los proveedores reales listados en proveedores_validados si el usuario pregunta por eso; si no hay datos ahi que respondan la pregunta, dilo con honestidad en vez de inventar.\n\nIntencion detectada: ${intencion}.\npedidos_recientes: ${JSON.stringify(pedidosResumen)}\nproveedores_validados: ${JSON.stringify(proveedoresResumen)}`;

return [{
  json: {
    run_id: $('Registrar inicio de agente').item.json.run_id,
    openaiPayload: {
      model: 'gpt-4o-mini',
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: mensaje },
      ],
      temperature: 0.7,
      max_tokens: 300,
    },
  },
}];

const resp = $json;
let reply, statusValue, inputTokens = null, outputTokens = null;

if (resp.error || !resp.choices || !resp.choices.length) {
  statusValue = 'fallido';
  reply = 'Estoy teniendo un problema tecnico para responder en este momento. Por favor intenta de nuevo en unos minutos, o cuentame de otra forma en que puedo ayudarte con tu recuerdo.';
} else {
  statusValue = 'completado';
  reply = resp.choices[0].message.content.trim();
  if (resp.usage) {
    inputTokens = resp.usage.prompt_tokens;
    outputTokens = resp.usage.completion_tokens;
  }
}

return [{
  json: {
    run_id: $('Preparar prompt Alma').item.json.run_id,
    reply,
    status: statusValue,
    input_tokens: inputTokens,
    output_tokens: outputTokens,
    evaluation_flags: [],
  },
}];

const body = { status: $json.status, reply: $json.reply };
if ($json.input_tokens != null || $json.output_tokens != null) {
  body.metrics = { input_tokens: $json.input_tokens, output_tokens: $json.output_tokens };
}
if ($json.evaluation_flags && $json.evaluation_flags.length) {
  body.evaluation = { flags: $json.evaluation_flags };
}

return [{ json: { run_id: $json.run_id, bodyString: JSON.stringify(body) } }];
